import{socialScene,resolveSocialScene,initNeighbors}from './neighbors.js';
import{memoryInfluence}from './life-state.js';
import{mix}from './world.js';
export function relationshipStage(f){return !f?.met?'처음 만나는 사이':f.bond>=65?'가까운 친구':f.bond>=35?'편안한 사이':f.bond>=15?'익숙해지는 사이':'서로 살피는 사이'}
export function initSocial(s){if(s.socialVersion===1)return;s.socialVersion=1;s.areaId=`${s.home}:0`;s.areaSerial=0;s.oldFriends=[];const old=s.friend;if(old?.met){s.oldFriends.push({...old,id:'legacy',area:'unknown',bond:s.dogBond,meetings:0});s.friend={name:'흰 발끝의 개',met:false};s.dogBond=0;if(s.pending?.id==='dog-meet'){s.pending=null;s.log.push({day:s.day,id:'social-context',text:'예전 만남은 기억으로 남아 있다. 지금 사는 곳에서는 새로운 만남이 이어진다.'})}}s.friend={...s.friend,id:`friend-${s.areaId}`,area:s.areaId,bond:s.dogBond||0,meetings:0,lastMet:null};}
export function changeArea(s,reason){initSocial(s);if(s.friend.met)s.oldFriends.push({...s.friend});s.areaSerial++;s.areaId=`${s.home}:${s.areaSerial}`;s.encounterBase=s.encounters;s.visitorArea=null;if(s.storyCounts){s.storyCounts.encounter=0;s.storyCounts.door=0;}const names=['흰 발끝의 개','목소리가 낮은 개','꼬리가 둥글게 말린 개','갈색 얼룩이 있는 개'];s.friend={id:`friend-${s.areaId}`,area:s.areaId,name:names[(s.seed+s.areaSerial)%names.length],met:false,bond:0,meetings:0,lastMet:null};s.dogBond=0;s.lastAreaChange={day:s.day,reason};initNeighbors(s);}
export function canMeetFriend(s){const a=s.neighborhood?.animals.find(x=>x.id===s.friend?.id);return (!a||a.alive!==false&&a.area===s.areaId)&&!s.story?.lost&&s.friend?.area===s.areaId&&(s.home!=='family'||(s.story.care==='normal'&&(!s.story.settleAt||s.day>=s.story.settleAt)));}
export function friendPresent(s){return canMeetFriend(s)&&s.friend.met&&s.friend.lastMet===s.day;}
export function friendPrompt(s){return socialScene(s)}
export function meetFriend(s,id,log,remember,clamp){if(!canMeetFriend(s))return;if(resolveSocialScene(s,id,log,remember,clamp))return;const f=s.friend,previous=relationshipStage(f);f.caution??=35;f.conflict??=0;
if(id==='retreat'||id==='sniff'){f.met=true;f.meetings++;f.lastMet=s.day;f.caution=clamp(f.caution+(id==='retreat'?2:-2));s.stress=clamp(s.stress-2);remember(s,id==='retreat'?'dog-space':'dog-disengage');log(s,'dog-friend',`${f.name}와 ${f.meetings}번째 만남. ${id==='retreat'?'거리를 벌리자 상대도 멈췄다. 쫓기지 않고 각자 길로 간다.':'바닥을 살피는 동안 상대가 천천히 지나갔다. 가까이 인사하지 않고 만남을 마쳤다.'}`);return;}
const chance=Math.min(.96,.52+f.bond/240+s.worldModel.traits.sociability/600-s.stress/500+memoryInfluence(s,f.id)/100);const roll=mix(s.seed+s.day,f.meetings+117)/4294967296;
if(id==='greet'&&roll>chance){f.met=true;f.meetings++;f.lastMet=s.day;f.bond=clamp(f.bond-2);f.caution=clamp(f.caution+6);f.conflict++;s.dogBond=f.bond;s.stress=clamp(s.stress+4);remember(s,'dog-caution');log(s,'dog-friend',`${f.name}와 ${f.meetings}번째 만남. 가까워지자 상대 몸이 굳었다. 더 다가가지 않고 거리를 벌리자 서로 다른 쪽으로 움직였다.`);return;}
f.caution=clamp(f.caution-4);f.met=true;f.meetings++;f.lastMet=s.day;f.bond=clamp(f.bond+(id==='greet'?14:f.bond<35?3:1));s.dogBond=f.bond;s.stress=clamp(s.stress+(id==='greet'?-3:0));remember(s,'dog-friend');const n=(f.meetings-1)%3;let text;if(id==='watch')text=['서로 다가오지 않고 기다린다. 무리하지 않는 거리가 조금 익숙해진다.','같은 자리에 잠시 머문다. 상대도 내 거리를 지켜 준다.','나란히 떨어져 주변을 살핀다. 가까이 가지 않아도 전보다 편안하다.'][n];else if(f.bond<35)text=['짧게 냄새를 맡고 물러난다. 서로의 얼굴을 조금 더 기억한다.','지난번보다 오래 인사한다. 꼬리가 천천히 움직인다.','먼저 코를 내밀자 상대도 몸의 힘을 푼다.'][n];else if(s.day>=2920)text=['친구와 보폭을 맞춰 천천히 걷는다. 서두르지 않아도 편하다.','풀그늘에서 친구와 나란히 쉰다. 익숙한 숨소리가 들린다.','몇 걸음 걷다가 함께 멈춘다. 서로의 느린 걸음을 기다린다.'][n];else text=['앞다리를 낮추고 놀이에 응한다. 번갈아 쫓고 쫓기며 달린다.','잠시 함께 걷다가 그늘에서 쉰다. 곁에 있어도 편안하다.','친구가 내민 나뭇가지를 건드린다. 둘이 장난치다 나란히 앉는다.'][n];log(s,'dog-friend',`${f.name}와 ${f.meetings}번째 만남. ${text}`);const next=relationshipStage(f);if(previous!==next)log(s,'relationship-stage',`${f.name}와 ${next}가 되었다. (${f.bond}/100)`);}
